head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > M > setSelectedIndex]<br/>Multiselect 컴포넌트에서 인덱스를 사용하여 특정 아이템들을 선택하거나 해제합니다.",
    "validation" : [
        "index(필수) 파라미터로 선택 또는 해제 할 아이템들의 인덱스를 separator 속성값의 구분자로 구분하여 설정합니다.",
        "아이템의 인덱스는 1 부터 시작합니다.",
        "이미 선택된 아이템은 해제되고, 선택되지 않은 아이템은 선택됩니다. (토글 동작)",
        "singleSelect=true 이면 첫 번째 인덱스의 아이템만 처리되며 나머지 아이템은 선택이 해제됩니다.",
        "존재하지 않는 인덱스는 처리되지 않습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (BindItemSet: gdl_multiselect 와 바인딩, separator/singleSelect 속성 적용)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // gdl_multiselect 재생성 (idempotent: 기존 dataList 제거 후 재생성)
    $c.gcm.createDataListMultiSelect();

    // separator 속성값 (con_separator 선택값)
    let cSeparator = con_separator.getText();
    // singleSelect 속성값 (con_singleSelect 선택값)
    let cSingleSelect = con_singleSelect.getText();

    let properties = {};
    if (cSeparator !== "") {
        properties.separator = cSeparator;
    }
    if (cSingleSelect !== "") {
        properties.singleSelect = cSingleSelect;
    }
    let cList = $c.gcm.createCList(properties);

    // 현재 적용된 속성 정보 라벨 표시
    let labelText = "target1 : separator=[" + (cSeparator === "" ? "미설정(기본 공백)" : cSeparator) + "]"
        + ", singleSelect=[" + (cSingleSelect === "" ? "미설정(기본 false)" : cSingleSelect) + "]";
    $c.gcm.createLabel('label="' + labelText + '"', '', 'label1');

    // comp 생성 함수 호출
    $c.gcm.createBasicMultiSelect(cList);
}



// setSelectedIndex(index) 호출 - par_index 입력값을 인자로 전달
scwin.btn_setSelectedIndex_onclick = function (e) {
    let index = par_index.getValue();
    target1.setSelectedIndex(index);
    wf_body_bottom.getObj("scwin").setReturnValue("target1.setSelectedIndex('" + index + "') 호출 완료");
};



// getSelectedIndex() 호출 - 현재 선택된 인덱스 확인
scwin.btn_getSelectedIndex_onclick = function (e) {
    let rtn = target1.getSelectedIndex();
    wf_body_bottom.getObj("scwin").setReturnValue("target1.getSelectedIndex() : [" + rtn + "]");
};



// 사전 선택 - 인덱스 1, 2 아이템 선택 상태로 설정 (토글 동작 검증용, 1-based)
scwin.btn_preSelect_onclick = function (e) {
    target1.setValue("");
    let cSeparator = con_separator.getText() || " ";
    target1.setSelectedIndex("1" + cSeparator + "2");
    wf_body_bottom.getObj("scwin").setReturnValue("target1 : 인덱스 1, 2 사전 선택 완료 (getSelectedIndex='" + target1.getSelectedIndex() + "')");
};



// setSelectedIndex 에 존재하지 않는 인덱스 포함하여 호출 (존재하지 않는 인덱스는 처리되지 않음, 1-based)
scwin.btn_setSelectedIndexInvalid_onclick = function (e) {
    let cSeparator = con_separator.getText() || " ";
    let inputVal = "1" + cSeparator + "99";
    target1.setSelectedIndex(inputVal);
    wf_body_bottom.getObj("scwin").setReturnValue("target1.setSelectedIndex('" + inputVal + "') 호출 완료 (99 는 존재하지 않는 인덱스)");
};



// 전체 선택 해제
scwin.btn_clearSelection_onclick = function (e) {
    target1.setValue("");
    target1.setInstanceValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1 : 전체 선택 해제 완료");
};
